const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Antarctic region (south of 60°S)
  const antarctic = ee.Geometry.Polygon(
    [[[-180, -60], [180, -60], [180, -90], [-180, -90], [-180, -60]]]
  );

  // 2. Get Sentinel-5P ozone data for September-October 2021 (peak ozone hole season)
  const ozoneCol = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_O3')
    .filterDate('2021-09-01', '2021-10-31')
    .filterBounds(antarctic)
    .select('O3_column_number_density');

  const colSize = ozoneCol.size().getInfo();
  console.log(`Images found: ${colSize}`);

  if (colSize === 0) {
    console.log("No Sentinel-5P ozone data available for 2021.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Calculate mean ozone for the period
  const meanOzone = ozoneCol.mean();

  // 4. Convert to Dobson Units (DU): 1 DU = 2.687e16 molecules/cm²
  // S5P provides mol/m² -> convert to DU
  const ozoneDU = meanOzone.multiply(2241.15); // conversion factor

  // 5. Create mask for ozone hole (< 220 DU)
  const ozoneHoleMask = ozoneDU.lt(220);

  // 6. Calculate area of ozone hole
  const pixelArea = ee.Image.pixelArea();
  const ozoneHoleArea = pixelArea.updateMask(ozoneHoleMask);

  const areaResult = ozoneHoleArea.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: antarctic,
    scale: 10000,
    maxPixels: 1e9
  }).get('area');

  const areaKm2 = ee.Number(areaResult).divide(1e6).getInfo();

  // 7. Count valid pixels
  const pixelCount = ozoneHoleMask.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: antarctic,
    scale: 10000,
    maxPixels: 1e9
  }).get('O3_column_number_density').getInfo();

  console.log(`Valid pixels in ozone hole: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log("No valid ozone hole pixels detected.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (areaKm2 === null || isNaN(areaKm2)) {
    console.log("Calculation failed to produce valid area.");
    console.log("<answer>C3</answer>");
    return;
  }

  console.log(`Ozone hole area: ${areaKm2.toFixed(2)} million km²`);
  console.log(`Threshold: 18 million km²`);

  if (areaKm2 >= 18) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
